"""First-screen editorial styling; original homepage copy stays in site_layout.py."""
import re

FIGURE = '<figure class="system-plate" aria-label="推理系统概念示意：请求进入推理引擎，由底层算力执行并返回输出。"><div class="plate-heading"><span>INFERENCE SYSTEM</span><span class="plate-status"><i></i> 执行链路</span></div><div class="request-pills"><span>实时对话</span><span>长文档</span><span>Agent</span></div><div class="flow-stem"><b></b></div><div class="engine-plane"><div class="engine-caption">推理引擎 <span>INFERENCE ENGINE</span></div><div class="engine-units"><span>请求调度</span><span>KV 状态</span><span>模型执行</span></div><div class="token-line"><span>输入</span><div class="token-stream"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><span>输出</span></div></div><div class="hardware-connect"><span></span><span></span><span></span></div><div class="hardware-row"><div class="chip"><span>GPU</span><div class="chip-grid"></div></div><div class="chip"><span>GPU</span><div class="chip-grid"></div></div><div class="chip alternate"><span>AI 加速器</span><div class="chip-grid"></div></div></div><div class="fabric-line"><span>设备互联与网络</span></div><figcaption>计算 · 状态 · 调度 · 通信</figcaption></figure>'

CSS = ".edition-line{display:flex;justify-content:space-between;align-items:center;padding:26px 0 22px;border-bottom:1px solid #bdc9bc;font:12px Georgia,serif;letter-spacing:.23em;color:#466a5b}\n.edition-line>span:last-child{font:11px sans-serif;letter-spacing:.18em;color:#738477}\n.editorial-hero-grid{display:grid;grid-template-columns:1.1fr 1fr;gap:7%;align-items:center;padding:68px 0 58px}\n.hero-kicker{display:flex;align-items:center;gap:9px;font-size:11px;letter-spacing:.15em;color:#687f70;margin-bottom:24px}.hero-kicker i{width:6px;height:6px;background:#9d7951;border-radius:50%}\nbody.is-home .home-hero h1{font-family:'Songti SC','STSong',serif;font-size:clamp(46px,5.3vw,76px);letter-spacing:-.045em;line-height:1.18;color:#1c3a30;margin:0 0 22px;font-weight:700}\n.home-hero h1>span{color:#567363}\nbody.is-home .home-subtitle{font-size:clamp(23px,2.35vw,33px);line-height:1.55;color:#496452;letter-spacing:.025em}\nbody.is-home .home-lead{font-size:13px;line-height:2;color:#738074;margin:24px 0 0;max-width:490px}\nbody.is-home .hero-actions{margin:28px 0 0;gap:24px}\nbody.is-home .primary-action{background:#274e3e;padding:13px 23px;border-radius:3px;font-size:12px;gap:30px;border:1px solid #274e3e;box-shadow:0 4px 12px #254d3910;transition:background .2s,transform .2s}\nbody.is-home .primary-action:hover{background:#39654f;transform:translateY(-2px)}\nbody.is-home .secondary-action{font-size:12px;color:#596e5e}\n.system-plate{margin:0;position:relative;padding:23px 27px 20px;background:radial-gradient(ellipse at 45% 25%,#e8eee2b0,transparent 70%),#f3f5ed;border:1px solid #d4ddcd;border-radius:4px;box-shadow:0 24px 50px -30px #2c513a40,inset 0 1px 0 #fff;overflow:hidden}\n.system-plate::before{content:'';position:absolute;inset:0;background-image:linear-gradient(#9eafa014 1px,transparent 1px),linear-gradient(90deg,#9eafa014 1px,transparent 1px);background-size:24px 24px;pointer-events:none}\n.system-plate>*{position:relative}.plate-heading{display:flex;justify-content:space-between;font:9px Georgia,serif;letter-spacing:.12em;color:#6e8671;margin-bottom:29px}.plate-status{font:9px sans-serif;letter-spacing:0;display:flex;gap:5px;align-items:center}.plate-status i{width:4px;height:4px;border-radius:50%;background:#6d9875}\n.request-pills{display:flex;justify-content:center;gap:10px}.request-pills span{background:#fcfdf8;border:1px solid #d2dcce;border-radius:4px;padding:7px 16px;font-size:10px;color:#5a7462}\n.flow-stem{height:30px;width:1px;background:#9aaa97;margin:auto;position:relative}.flow-stem b{position:absolute;bottom:0;left:-3px;border-top:5px solid #78947c;border-left:3px solid transparent;border-right:3px solid transparent}\n.engine-plane{padding:19px 22px;background:#fffefa;border:1px solid #a8bca6;border-top:3px solid #47705a;box-shadow:0 7px 18px #355c3a0c;border-radius:4px}.engine-caption{font-size:14px;font-weight:600;color:#36583f;display:flex;justify-content:space-between;align-items:center}.engine-caption>span{font:8px Georgia,serif;letter-spacing:.1em;color:#8a9b85}.engine-units{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:15px}.engine-units span{font-size:10px;text-align:center;padding:9px 0;border:1px solid #dbe3d6;background:#f1f5ed;border-radius:3px;color:#647c62}.token-line{display:flex;align-items:center;gap:12px;font-size:8px;color:#8c9b87;margin-top:16px}.token-stream{display:flex;align-items:center;justify-content:space-between;flex:1;gap:5px}.token-stream i{height:5px;flex:1;background:#bdd0b5;animation:token-glow 3.6s ease-in-out infinite}.token-stream i:nth-child(3n){animation-delay:.6s}.token-stream i:nth-child(3n + 1){animation-delay:1.2s}\n.hardware-connect{display:flex;justify-content:space-around;height:25px}.hardware-connect span{width:1px;background:#a4b79e}.hardware-row{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;padding:0 8px}.chip{position:relative;padding:11px;background:#e5eddf;border:1px solid #aabca2;outline:1px dashed #bbc9b2;outline-offset:3px;border-radius:3px;text-align:center}.chip>span{font:11px Georgia,serif;color:#4d7151}.chip.alternate{background:#eee8da;border-color:#c3b596;outline-color:#cfc4ad}.chip.alternate>span{font:10px sans-serif;color:#8a7655}.chip-grid{margin-top:8px;height:25px;background:repeating-linear-gradient(90deg,transparent 0 8px,#aac39b55 8px 10px),repeating-linear-gradient(0deg,#c2d4b5 0 5px,#e0ead7 5px 7px);border:1px solid #bbccaf;opacity:.7}.alternate .chip-grid{filter:sepia(.5)}\n.fabric-line{margin:19px 8px 0;border-top:1px solid #afbea6;display:flex;justify-content:center}.fabric-line span{margin-top:-7px;padding:0 10px;background:#f3f5ed;font-size:8px;color:#8a9b82}.system-plate figcaption{font-size:9px;color:#869681;letter-spacing:.16em;text-align:center;margin-top:20px}\nbody.is-home .home-facts{display:grid;grid-template-columns:repeat(3,1fr) 1.1fr;gap:0;padding:25px 0;border-top:1px solid #bac9b7;border-bottom:1px solid #bac9b7;background:linear-gradient(90deg,#e9eee344,transparent)}\nbody.is-home .home-facts>div{min-width:0;background:none;box-shadow:none;border:0;border-right:1px solid #d8dfd1;border-radius:0;display:flex;align-items:center;gap:16px;padding:0 25px;overflow:hidden}\nbody.is-home .home-facts>div:first-child{padding-left:0}body.is-home .home-facts>div:hover{transform:none;box-shadow:none}body.is-home .home-facts strong{font:38px Georgia,serif;color:#3c6650}body.is-home .home-facts span{font-size:11px;color:#536b58;line-height:1.6}.home-facts small{display:block;font-size:9px;color:#8a9787;margin-top:4px}.fact-explore{display:flex;align-items:center;justify-content:space-between;padding-left:34px;font-size:11px;color:#688068}.fact-explore>span{font-size:18px;color:#8b744f}\n\n.home-hero{border-bottom:0;padding:0 0 12px}\nbody.is-home .home-hero h1{font-size:clamp(34px,3.7vw,58px);white-space:nowrap}\nbody.is-home .home-subtitle{font-size:clamp(20px,1.8vw,28px)}\n.editorial-hero-grid{gap:5%;padding:44px 0 42px;grid-template-columns:1.1fr 1fr}\n.hero-copy{min-width:0}.system-plate{min-width:0;padding:20px 18px}.plate-heading{margin-bottom:23px}\n.engine-plane{padding:16px}.request-pills span{padding:7px 10px}.hardware-row{gap:14px}\nbody.is-home .home-facts{grid-template-columns:repeat(3,1fr);padding:24px 0}\nbody.is-home .home-facts>div:last-child{border-right:0}\nbody.is-home .home-facts>div{gap:14px}\n@keyframes token-glow{0%,65%,100%{opacity:.5}30%{opacity:1;background:#6d9c73}}\n@media(max-width:900px){.editorial-hero-grid{grid-template-columns:1fr;gap:32px}.system-plate{width:100%;max-width:470px;box-sizing:border-box;justify-self:center}body.is-home .home-hero h1{font-size:48px}}\n@media(max-width:760px){.edition-line{padding:6px 0 18px;font-size:10px}.editorial-hero-grid{padding:28px 0 32px}.system-plate{padding:21px}body.is-home .home-hero h1{font-size:42px;white-space:normal}body.is-home .home-subtitle{font-size:23px}body.is-home .home-lead{font-size:12px;line-height:2;margin-top:18px}body.is-home .hero-actions{margin-top:22px;gap:18px}body.is-home .primary-action{padding:11px 17px}body.is-home .home-facts>div{display:flex;padding:0 10px;gap:8px}body.is-home .home-facts strong{font-size:30px}body.is-home .home-facts span{font-size:10px}.engine-caption>span{font-size:7px}}\n@media(prefers-reduced-motion:reduce){.token-stream i{animation:none}.primary-action{transition:none}}\n"

def decorate_home(page):
    match = re.search(r'<header class="home-hero">(.*?)</header>', page, re.S)
    original = match[1]
    eyebrow = re.search(r'<div class="home-eyebrow">(.*?)</div>', original, re.S)
    facts = re.search(r'<div class="home-facts">.*', original, re.S)[0]
    copy = original[eyebrow.end():original.index('<div class="home-facts">')]
    header = ('<header class="home-hero"><div class="edition-line"><span>' + eyebrow[1] + '</span></div>'
              + '<div class="editorial-hero-grid"><div class="hero-copy">' + copy + '</div>' + FIGURE + '</div>' + facts + '</header>')
    return page[:match.start()] + header + page[match.end():]
